import { deflateSync } from 'node:zlib';
import { describe, expect, it } from 'vitest';
import { decodePng } from '../src/lib/formats';

// Independent PNG container builder: packed scanlines and expected decoded
// pixels are supplied explicitly, rather than generated by our PNG encoder.
function crc32(bytes: Uint8Array): number {
  let crc = 0xffffffff;
  for (const byte of bytes) {
    crc ^= byte;
    for (let bit = 0; bit < 8; bit++) crc = crc & 1 ? 0xedb88320 ^ crc >>> 1 : crc >>> 1;
  }
  return (crc ^ 0xffffffff) >>> 0;
}
function chunk(type: string, bytes: number[] | Uint8Array): Uint8Array {
  const data = Uint8Array.from(bytes), result = new Uint8Array(data.length + 12), view = new DataView(result.buffer);
  view.setUint32(0, data.length);
  result.set(new TextEncoder().encode(type), 4); result.set(data, 8);
  view.setUint32(data.length + 8, crc32(result.subarray(4, data.length + 8)));
  return result;
}
function png(width: number, height: number, depth: number, colorType: number, rows: number[], palette?: number[], transparency?: number[]): ArrayBuffer {
  const header = new Uint8Array(13), view = new DataView(header.buffer);
  view.setUint32(0, width); view.setUint32(4, height); header[8] = depth; header[9] = colorType;
  const chunks = [new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', header)];
  if (palette) chunks.push(chunk('PLTE', palette));
  if (transparency) chunks.push(chunk('tRNS', transparency));
  chunks.push(chunk('IDAT', deflateSync(new Uint8Array(rows))), chunk('IEND', []));
  const result = new Uint8Array(chunks.reduce((total, part) => total + part.length, 0));
  let offset = 0;
  for (const part of chunks) { result.set(part, offset); offset += part.length; }
  return result.buffer;
}

describe('packed PNG and transparency interoperability', () => {
  const palette = [11, 22, 33, 201, 19, 91, 7, 99, 13];
  const expected = [
    11, 22, 33, 255, 201, 19, 91, 128, 7, 99, 13, 0,
    7, 99, 13, 0, 201, 19, 91, 128, 11, 22, 33, 255,
  ];
  it.each([
    [2, [0, 0x18, 0, 0x90]],
    [4, [0, 0x01, 0x20, 0, 0x21, 0x00]],
    [8, [0, 0, 1, 2, 0, 2, 1, 0]],
  ] as const)('reads a %i-bit indexed PNG with row padding and tRNS without changing RGB', (depth, rows) => {
    const restored = decodePng(png(3, 2, depth, 3, [...rows], palette, [255, 128, 0]), 'indexed.png');
    expect([...restored.frames[0].pixels]).toEqual(expected);
  });
  it('reads 1-bit indexed PNG rows independently including a partial-alpha entry', () => {
    const buffer = png(3, 2, 1, 3, [0, 0x40, 0, 0xa0], [5, 20, 40, 210, 90, 60], [255, 80]);
    expect([...decodePng(buffer, '1bit.png').frames[0].pixels]).toEqual([
      5, 20, 40, 255, 210, 90, 60, 80, 5, 20, 40, 255,
      210, 90, 60, 80, 5, 20, 40, 255, 210, 90, 60, 80,
    ]);
  });
  it('expands a 1-bit grayscale PNG with a transparent grayscale key', () => {
    const restored = decodePng(png(5, 2, 1, 0, [0, 0x58, 0, 0xa0], undefined, [0, 0]), 'gray.png');
    const expected = [0, 1, 0, 1, 1, 1, 0, 1, 0, 0].flatMap((value) => [value * 255, value * 255, value * 255, value * 255]);
    expect([...restored.frames[0].pixels]).toEqual(expected);
  });
  it('preserves 8-bit grayscale-alpha rather than using its alpha as a color channel', () => {
    const restored = decodePng(png(2, 1, 8, 4, [0, 17, 1, 129, 128]), 'gray-alpha.png');
    expect([...restored.frames[0].pixels]).toEqual([17, 17, 17, 1, 129, 129, 129, 128]);
  });
  it('honors a truecolor tRNS key while preserving hidden RGB', () => {
    const restored = decodePng(png(2, 1, 8, 2, [0, 11, 22, 33, 12, 22, 33], undefined, [0, 11, 0, 22, 0, 33]), 'rgb-key.png');
    expect([...restored.frames[0].pixels]).toEqual([11, 22, 33, 0, 12, 22, 33, 255]);
  });
  it('also accepts a one-pixel RGB PNG with a transparent color key', () => {
    const buffer = png(1, 1, 8, 2, [0, 11, 22, 33], undefined, [0, 11, 0, 22, 0, 33]);
    expect([...decodePng(buffer, 'single-pixel.png').frames[0].pixels]).toEqual([11, 22, 33, 0]);
  });
  it('still rejects a corrupt CRC in the small-image tRNS compatibility path', () => {
    const buffer = png(1, 1, 8, 2, [0, 11, 22, 33], undefined, [0, 11, 0, 22, 0, 33]);
    // Signature(8) + IHDR(25) + tRNS length/type(8) puts the key at byte41.
    new Uint8Array(buffer)[41] ^= 1;
    expect(() => decodePng(buffer, 'broken.png')).toThrow(/CRC/);
  });
});
